class Episode:
    steps = _via('budget', 'steps')
    step_cap = _via('budget', 'step_cap')
    messages_used = _via('budget', 'messages_used')
    message_cap = _via('budget', 'message_cap')
    last_chance = _via('budget', 'last_chance')
    holds = _via('lines', 'holds')
    first_held_step = _via('lines', 'first_held_step')
    fits = _via('lines', 'fits')
    fit_steps = _via('lines', 'fit_steps')
    checked_prices = _via('lines', 'checked_prices')
    last_verdicts = _via('lines', 'last_verdicts')
    judge_alternative = _via('lines', 'judge_alternative')
    qlog = _via('lines', 'qlog')
    verified_lines = _via('lines', 'verified_lines')
    records = _via('store', 'records')
    known_ids = _via('store', 'known_ids')
    exec_log = _via('store', 'exec_log')
    price_cap = _via('budget', 'cap')
    basket_total = _via('budget', 'basket_total')
    pointers_read = _via('refs', 'pointers_read')
    pointer_calls = _via('refs', 'pointer_calls')
    reference_ignored = _via('refs', 'ignored')
    reference_unproven = _via('refs', 'unproven')
    reference_checks = _via('refs', 'checks')
    resolved_values_written = _via('refs', 'values_written')
    judge_contradictions_of_resolved = _via('refs', 'judge_contradictions')
    shadow_ref_value_misses = _via('refs', 'shadow_misses')
    shadow_ref_value_agreed = _via('refs', 'shadow_agreed')
    search_tools = _role('search_tools')
    open_record_tools = _role('open_record_tools')
    basket_change_tools = _role('basket_change_tools')
    message_tool = _role('message_tool')
    order_call_name = _role('order_call', 'name')
    decline_call_name = _role('decline_call', 'name')

    def __init__(self, problem: dict) -> None:
        env = _as_dict(problem.get('environment'))
        policy = _as_dict(env.get('policy_view'))
        self.binding = dict(env.get('binding') or {})
        self.request = str(policy.get('query') or problem.get('query') or '')
        self.opening = policy.get('opening')
        self.tools = []
        for t in policy.get('tools') or []:
            if isinstance(t, dict) and isinstance(t.get('function'), dict):
                self.tools.append(t)
            elif isinstance(t, dict) and isinstance(t.get('name'), str):
                self.tools.append({'type': 'function', 'function': t})
        self.raw_tools = _as_list(policy.get('tools'))  # handed to the toolkit seat verbatim
        self.tool_names = [str(t['function'].get('name')) for t in self.tools]
        self.state = EpisodeState(int(_num(policy.get('max_steps')) or 38))
        self.finished = bool(policy.get('finished'))
        self.task = str(problem.get('problem_id') or problem.get('id') or 'task')
        try:
            self.env = ProxyClient(timeout=90, max_retries=2)
        except TypeError:
            self.env = ProxyClient()
        self.model = ModelClient()
        self.model.budget = self.state.budget
        self.meter = {**dict.fromkeys(METER_COUNTS, 0), **{name: {} for name in METER_BOOKS}}  # METER1: telemetry counters under their spend-note key names, written by inc() / tally()
        self.budget_stop = False  # a loop turn the budget left no model for: the finish sequence takes over
        # counters and trace
        self.ledger = []
        self.history = []  # the conversation with the loop model: assistant calls and tool-role replies
        self.outbox = []  # program notes the model must read, attached to the reply of the call that caused them
        self.calls_made = 0  # tool-call ids handed to the history
        self.idle_turns = 0  # turns in a row that held words and no call
        self.idle_turns_total = 0
        self.inference_failures_in_row = 0  # loop turns in a row whose model list gave nothing usable
        self.turn_render_errors = 0  # loop turns skipped because the status render or a call's reply raised RuntimeError (TURN_RENDER_ERRORS_MAX)
        self.batch_tools = set()  # tools that open several listing records in one call (found from the call arguments)
        self.budget_tools = {}  # tools whose reply is this episode's own step / message budget, kept current here
        self.row_copy_views = {}  # record tools whose reply to a listing the search rows already showed was that row: the keys the reply carried
        self.row_copy_off = set()  # record tools whose reply differed from the row once: never answered from a row
        self.tool_owners = {}  # tool name -> the release test (or None) of the mechanism that owns the tool this turn (owns())
        self.refopen_queue = {}  # REFOPEN1 f: per open reference (its words), the seller's listed rows not yet opened
        self.refopen_continued = 0
        self.in_value_search = False  # VALUESEARCH1 guard
        self.askgate_held = 0  # ASKGATE1: the loop's own messages held while the program's plan is still to run
        # GATES1 (owner directive 11-06 15:44, design rule 15:45): no program gate refuses the loop a store capability because the program could
        # not read the reply, and no gate second-guesses the model without a bound. gate_fallback: the count-keyed gates that fell back to
        # call-based counts (open calls made, steps spent) because no opened record read as a card; gate_advised: the calls that went through
        # with the program's reading attached where the program used to turn them back (the note check's faults, a repeated failed check, the
        # closing call before its check, a duplicate note, the ask-gate past its hold cap).
        self.gate_fallback = {}
        self.gate_advised = {}
        # SHAPEKEYS1 (lead note 11-06 16:20, the r15 winner's design): on the FIRST reply of each listing tool a seat names the reply's parts
        # by the reply's own keys - the rows list, the match count, the next-page value and the parameter that takes it, and inside an entry
        # the id, the price and the in-stock flag; code grounds every name in the reply (or the tool's parameters) and the program reads
        # replies through the learned names from then on (rows_of, reply_count, row_price, row_buyable, next_page_by_shape); the
        # structure-only readers (table_rows, scalar_facts, the text reader) stay as the fallback. One call per tool per episode, never more.
        self.interview_send_cap_once = 0  # GATES1 d: a bound on the questions the next plan sends (one, at the loop's early message, on a one-line list); 0 = the plan's own count
        self.shape_keys = {}  # tool -> part -> key (rows, count, next, next_param, id, price, stock)
        self.shape_keys_asked = set()
        self.shape_keys_used = {}  # reads that went through a learned name, per part
        # ASKSHAPE1: on a multi-line request the plan's questions go out as one LIST question per line (the line's item and several of its
        # listed property names in one message) while the shopper takes such messages; after the first push-back read as asking for the
        # questions singly, this episode's questions are single questions again, for good. fired: multi-line plans that offered a list;
        # acted: list questions sent; fell_back: push-backs that closed the shape; by_shape: messages and answered messages per shape
        self.askshape_lists_ok = ASKSHAPE_LISTS_FIRST
        # ASKLINE1: on a multi-line list the plan is given each line's store shelf label (found by repetition over the line's own rows and
        # records) and names the item by it. lines: plan lines given a label; q_labeled / q_unlabeled: plan questions sent carrying it or not
        self._askline_cache = {}
        self.line_merges = 0  # LINEMERGE1: twin wanted lines the store's own repeated label named together, joined into one
        self.linemerge_kept_apart = set()
        self.interview_staged = False  # STAGED1: a one-line list's first plan sent part of its questions; a second plan is due
        self.tail_searches = 0  # TAILSEARCH1: program searches for the listing a chain card's pointer names
        self.hop_budget_added = 0.0  # HOPBUDGET1: dollars added to the ceiling for the hops followed
        self.tail_retried = set()  # TAILRETRY1: pointers whose tail search was retried once their card became a chain card
        self.pointer_reread = set()  # CHAINREREAD1: chain cards read again alone (once each)
        self.self_stated = set()  # cards whose text states the property itself (no handover)
        self.chain_rereads = 0
        self.head_figure_tries = {}  # HEADFIG1: seat calls per described figure (two at most)
        self.head_figure_seq = {}  # HEADFIG1 c: a head's decimal figure -> the words of the same amount in other units, each amount's words in order
        self.head_figure_forms = {}  # HEADFIG1: a head's decimal figure -> the number words of the same amount in other units (the seat's arithmetic)
        self.head_rows_none = set()  # HEADSEARCH1 e: search replies whose seller rows the seat read and named none of
        self.lineopens_marks = set()  # LINEOPENS1: basket states the unfilled-line opens ran for
        # FIRSTCLOSE1: finish-time row opens weighed against the steps the hold and the closing call need after them (fired: finish
        # passes that weighed opens; opens_withheld: opens not made for want of that room; blocked_by: the reason)
        # TRIALHELD16 a (SIBLINGFILE) counters: filings on a sibling list where the item test decided (fired), of them decided otherwise than
        # the word-overlap rule would have (acted), and the filings it left to that rule by reason (blocked_by); the other TRIALHELD16
        # counters stand at 0 on this head (the register found no row-level open rule and no judge-verdict class to build on that store)
        self.th_file_fired = 0
        self.th_file_acted = 0
        self.th_file_blocked_by = {}
        self._th_sibling_cache = ((), False)
        self._th_text_cache = (-1, {})
        self._th_decided = set()  # the distinct texts the item test decided (fired once each)
        self._th_changed = set()  # the distinct (kind, text or listing, line) filings decided otherwise than the overlap
        self.dualview_opened = 0  # the other view opened by the program (one step each)
        self.dualview_asked = set()  # (listing, view) pairs the program asked once
        # VIEWLATE1 (C568, the C555 rider): on a store whose record is split over views (one view the table, another the number), the stored
        # two-view reads had the program open the price view one step BEFORE its own hold on 31 of 33 ordered listings viewed before their add,
        # and the request's rule that every ordered listing's price view comes after its last add held on 5 of 20 ordered episodes. The program
        # now reads that view once AFTER the listing's add (its own hold, a cheaper-look swap, the check of a loop-held listing), and a trial of
        # a listing whose newest listed row carries its number and flag runs on the row without the pre-trial view (the same count, moved).
        self.viewlate_adds = {}  # per listing, the step of its last add (a basket change that put it in or raised its count)
        self.viewlate_bag = {}  # the replayed basket after the last basket change (adds are told from releases on it)
        self.viewlate_asked = set()  # (listing, add step) pairs the post-add view was asked for once
        self.frf1_row_priced = set()  # FINISHRIDERS1 FC1: listings whose pre-trial price view the finish deferred past the add (their newest row prices them until the view is read)
        # DOWNCONV1 (DC1): the post-add view is part of the order on a split-view store. Stored split-view head reads (two heads, 180 episodes):
        # 10 ordered episodes failed the request's view-after-add rule, 9 of them with VIEWLATE1 withholding the view for the reserve
        # (`no_steps`) after the program's own finish hold or sold-out swap, the loop then re-adding the same listing or viewing the basket
        # with the steps the view needed; 3 of the 10 had every need revealed and a basket the key accepts. The view the program's own add owes is
        # read inside the reserve (the closing call alone is kept), every held listing's due view is read once more right before a closing
        # call while the view and the call still fit, and a loop basket call that repeats the basket's own state is answered without a step.
        # REFVIEW1 (the PARKREVIEW2 REFS rider): on a store whose record is split over views the program's own chain open (a pointer row
        # opened off a search reply) lands on the facts view - a table, no price, no seller, no pointer passage - while the passage naming
        # the chain's next hop and the seller the binder reads sit on the price view alone. Stored r16 head reads: 298 of 298 program chain
        # opens through the facts view; of 102 chain heads the program opened, the price view was never read on 65 and came a median 10 steps
        # later on the rest (one at s31 with 4 steps left, declined), and no hop binds on the facts view (the seller is not on it), so the
        # program went on opening the seller's other rows (174 cascade opens for 19 hops). The price view is now read in the same move.
        # RESERVEVIEW1 (REFVIEW1 rider 1): the 0-step re-serve of an open let another view's card stand in for the asked view whenever the
        # card carried a property table. On a store whose record is split over views that is the facts card answering the loop's ask of the
        # price view: 241 of 241 re-serves on ten r16 head reads, the price view never read on 124 of them. The stand-in now needs the
        # number the asked view carries too; else the asked view's own earlier reply serves, or the call goes to the store.
        # CHAINEND1 (see read_pointers): the pointer seat types the values a chain card's own text gives for the properties handed to it (end_values, each with its quote);
        # a chain ending on a card whose property table shows no value under the chain's property takes that card's grounded text value
        self.ce1_opened_for = {}  # listing id -> the descriptions (normalised) the program opened it for
        self.ce1_end_from_text = set()  # (end card, property) chains that ended on a text value
        # POINTERBUDGET1 (REFS): on a store whose record is split over views the facts view carries the table and the listing's headline -
        # the headline its listed row already showed - and no passage; the pointer passage sits on the priced view. Stored r16 head reads
        # (630 episodes): 5,724 of 6,670 pointer calls read such cards (10 entries found, no true handover), the seat's 12-read budget then
        # turned away 1,949 reads (341 of them priced views), and a facts card read first marked the listing read, so its priced view was
        # never sent on 407 of 812 opens of a listing whose priced view carried a passage (21 of them chain cards).
        self.pb1_reached = set()  # listings whose skipped card fit an open reference's description
        # SRCHLINE1 (C568 PARKREVIEW2 item K, re-implemented from 67ddb887): an opened card is filed under the line its open call NAMED - a
        # program open made for a line (the visibility, ask-gate and line-rows openers), or the loop's line_index - before any word overlap
        # with the line words; the basket check's filing and a seat-verified fit still come first. Stored reads: program opens made for a
        # line were trialled for another line 36 times in 270 episodes; by the key the named line was the right one on 8, the word-filed
        # line on 1.
        self.srchline_fired = 0  # listings whose line_of was answered by a named open (once per listing and line)
        self.srchline_overruled = 0  # of those, where the word overlap would have filed the card under another line
        self._srchline_seen = set()
        # LIST3 OPENEDTRIAL1 counters: moments the precondition held (a list of OPENED_TRIALS_LINES_MIN lines or more with a wanted line that holds no
        # fit and has opened, untried, buyable records of its own), trials made, trials that filled a line, moments blocked by reason
        self.list3_plan_done = False  # the plan-moment trials ran once (after the program's questions went out)
        self.list3_plan_allowance = {}  # LIST3: plan-moment trials made per line - each one widens that line's trial cap by one (the loop's own allowance stays)
        self.trial_block = ''  # LIST3: why the last hold trial asked for was not made ('' when it was)
        self.chain_walk_turns = 0  # CHAINFINISH1: turns the ordering call was withheld for the chain walk
        self.chain_walk_ghost_ids = set()  # CHAINFINISH1: references the shopper freed whose chain the program went on walking
        self.rr2_closed = set()  # REPLYREF2 c: references the turn start closed from the ledger binding (once each; a reopen is the check's to read)
        self.rr2_pair_tried = set()  # REPLYREF2 c: (reference, end record) pairs whose counterpart the turn start tried to bind once
        self.rr2_searched = {}  # REPLYREF2 c: reference -> the resolved value its value search went out for (once per value)
        self.refopen_queued_keys = set()  # DEADEND1 b: reference keys the program queued seller rows for at least once
        self.tail_done = {}  # DEADEND1: pointer -> the step at which the program's search for its listing was made (or read)
        self.tail_search_steps = set()  # HEADOWN1: the steps of the program's own searches for a chain card's pointed listing
        self.head_searches = 0  # HEADSEARCH1: program searches for the listing a requirement itself points at (the chain's head)
        self.head_rows_read = set()  # HEADSEARCH1: steps of the searches whose rows the head opener already read
        self.head_opens = 0  # HEADSEARCH1 b: the seller's best-ranked listed row opened by the program for a chain's head
        self.pointer_chain_reads = 0  # PTRBUDGET1: pointer reads made while a reference chain was open, outside the seat's call budget
        self.narrow_query_hits = dict(zero=0, page=0, wide=0)  # per reference, what its first query (seller + kind of item) returned
        self.needs_by_line = {}  # per wanted line (by index): the cards needed now and not in hand, derived at render
        self.last_batch_offer = []  # the ids the status last offered to open (one batch call, or one call each)
        self.last_offer_batched = False  # whether that offer was one batch call (else one open per id)
        self.terminal_1hop = set()  # listings the shopper described that ended their own chain (no card hands the property on; its own table shows the value)
        self.status_chars = []  # per loop turn, the characters of the closing note (status and carried lines): the part of the prompt no cache holds
        # STATUSCACHE1: the status notebook. A status block that stays the same from turn to turn (a record's facts, an instruction the
        # program keeps or has done, a resolved reference, FIT IN HAND, the brief as changed by a reply) is written into the conversation
        # ONCE, appended to its last message (cached from the next turn on, as the history is), and the closing note carries a pointer to it
        # while it is unchanged; a changed block is written again. Per block key: the text last written and the turn it was written at.
        self.notebook_sent = {}
        self.notebook_turn = {}
        self.sc_status_chars = []  # per loop turn, the characters of the note as sent (the carried lines, the status with its pointers, the brief block)
        self.sc_notebook_chars = []  # per loop turn, the characters written into the conversation as that turn's notebook entry
        self.sc_full_chars = []  # per loop turn, the characters the status would have had with every block in the note (what the previous head sent)
        self.ended = False  # the neutral finish has run
        self.brief_dump = ''  # the brief as the conversation's first message carried it
        self.last_message_step = -1
        self.basket_seen = None
        self.basket_step = -1
        self.basket_calls = []
        self.basket_views = 0  # times the store's own basket view was read
        self.changes_since_view = 0  # basket-change calls made since the store last showed the basket
        self.basket_touched = False
        self.searched_ok = False
        self.rejections_in_row = 0
        self.contract_errors = 0
        self.order_ready = False
        self.decline_ready = False
        self.view_seen = None
        self.view_step = -1
        self.asked_replies = []
        self.last_basket_change_step = -1
        self.verify_runs = 0
        self.time1_fired = 0
        self.time1_acted = 0
        self.turns_at_same_step = 0
        self.jc_cap = 0  # the judge seat's call budget for this episode (set once the brief is read)
        self.judge_cache = {}  # the judge's report per body of evidence: the same evidence is judged once
        self.last_verdict_text = ''
        # JUDGEFIN1: a judge answer that left a verdict gap (a held listing no line names and no line verdict for it, a requirement with no
        # entry, a quote not in its record) is asked once more over the same evidence; per site (finish / hold): gaps seen, retries made,
        # retries that closed the gap, and why a gap went unretried
        self.judge_gap = ''  # the last _verify_once's gap kind ('' when the answer left none)
        self.judge_retry_stats = {}
        # JUDGEACT1: the judge's typed recommendation per line (action, target, property, level, quote), grounded and checked against the
        # line's own met flags by code, rendered as one fact by level (decisive first, advised after it, optional counted only); the loop
        # decides. fired = recommendations returned; shown = rendered after a real check; acted / ignored (per level) = what the loop's first
        # store call after the check did with it; blocked_by = why one was dropped
        self.ja_fired = 0
        self.ja_acted = {}  # per level: the loop's next call was the advised move on its target
        self.ja_recheck = {}  # per level: the loop ran the check or audit again instead
        self.ja_ignored = {}  # per level: the loop did something else
        self.ja_ungrounded = 0
        self.ja_contradiction = 0
        self.ja_recs = {}
