        self.change_rejudge_pending = False
        self.cp_change_step = -1  # the step of the last typed change
        self.cp_change_rejudge = 0  # judge calls the hook made after a change
        self.cp_hook_step = -1  # the step of the hook's last verdict, with what it asked of the basket (for the acted count)
