        self.ar_list_len_before = None  # names the full open list held at the first question
        self.ar_list_len_after = None  # entries the ranked shortlist held at the first question
        self.ar_first_question_rank = None  # rank in the shortlist of the property the first question asked (None: not in it)
        self.ar_tier_opens = 0  # rows the program opened at another price before the first question
